#!/usr/bin/env python3
# gen_spv_headers.py — canonical SPIR-V embed generator for the isp_spv dir.
#
# WHY THIS EXISTS
#   Each isp.* shader is compiled to SPIR-V and *embedded* into a C header
#   (`*_spv.h`) that IspSpvLookup.cpp #includes. VulkanFuse never opens the
#   loose `.spv` at runtime — only the embedded array reaches the device.
#   Those headers were previously regenerated by hand (gen_spv_h.py hard-codes
#   three names) and drifted badly: 22 of the 68 headers actually included by
#   IspSpvLookup.cpp embedded byte counts that no longer matched the compiled
#   shader. Editing a `.comp` silently did nothing on device, and one header
#   (g_isp_crop_blc_norm_cfa_spv.h) was not SPIR-V at all — a textual
#   `spirv-dis` dump pasted into a decimal array, so that pipeline was built
#   from garbage.
#
# WHAT IT DOES
#   Driven by the REAL include list in IspSpvLookup.cpp (so orphan headers are
#   left alone). For every included header:
#     1. resolve its declared symbol -> shader base (`g_isp_crop_blc_norm_cfa_spv`
#        -> `isp_crop_blc_norm_cfa`; a trailing `_spv` is optional)
#     2. compile `<base>.comp` (preferred) or `g_<base>.comp`
#     3. rewrite the header in place, KEEPING the existing symbol name (the
#        `extern` decls in IspSpvLookup.hpp depend on it)
#   Symbol names in this tree are not uniform, so the generator adapts to what
#   the header already declares instead of imposing a naming scheme.
#
# USAGE
#   python3 gen_spv_headers.py --check   # verify only; exit 1 if anything stale
#   python3 gen_spv_headers.py           # rewrite every stale header
#   python3 gen_spv_headers.py isp_ae    # only the named shader(s)

import os
import re
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
LOOKUP_CPP = os.path.join(HERE, "..", "IspSpvLookup.cpp")
GLSLANG = os.environ.get("GLSLANG", "glslangValidator")
SPIRV_MAGIC = b"\x03\x02\x23\x07"


def included_headers():
    """Headers actually #included by IspSpvLookup.cpp, in order."""
    src = open(LOOKUP_CPP).read()
    return re.findall(r'#include "isp_spv/([^"]+)"', src)


def header_symbol(path):
    text = open(path, "rb").read().decode("latin1")
    stripped = re.sub(r"//[^\n]*", "", text)
    m = re.search(r"const\s+unsigned\s+char\s+(g_[A-Za-z0-9_]+)\s*\[\s*\]", stripped)
    return m.group(1) if m else None


def header_payload(path):
    """(payload_bytes, declared_len) for a header, hex or decimal array."""
    text = open(path, "rb").read().decode("latin1")
    stripped = re.sub(r"//[^\n]*", "", text)
    hexbytes = re.findall(r"0x([0-9a-fA-F]{2})", stripped)
    if hexbytes:
        payload = bytes(int(x, 16) for x in hexbytes)
    else:
        m = re.search(r"=\s*\{([0-9,\s]+)\}", stripped)
        payload = (bytes(int(x) & 0xFF for x in re.findall(r"[0-9]+", m.group(1)))
                   if m else b"")
    lm = re.search(r"const\s+int\s+g_[A-Za-z0-9_]+\s*=\s*(\d+)", stripped)
    return payload, (int(lm.group(1)) if lm else -1)


def shader_base(symbol):
    b = symbol[2:] if symbol.startswith("g_") else symbol
    if b.endswith("_spv"):
        b = b[:-4]
    return b


def resolve_comp(base):
    """Prefer the exact <base>.comp; fall back to g_<base>.comp."""
    for cand in (base + ".comp", "g_" + base + ".comp"):
        p = os.path.join(HERE, cand)
        if os.path.exists(p):
            return p
    return None


def compile_comp(comp, out_spv):
    r = subprocess.run([GLSLANG, "-V", comp, "-o", out_spv],
                       capture_output=True, text=True)
    if r.returncode != 0:
        sys.stderr.write("glslangValidator FAILED for %s:\n%s%s\n"
                         % (os.path.basename(comp), r.stdout, r.stderr))
        return None
    return open(out_spv, "rb").read()


def write_header(path, symbol, payload):
    """Rewrite in place, same symbol, 16 bytes/line hex entries."""
    lines = ["const unsigned char %s[] = {" % symbol]
    for i in range(0, len(payload), 16):
        lines.append("".join("0x%02x," % b for b in payload[i:i + 16]))
    lines.append("};")
    lines.append("")
    lines.append("const int %s_len = %d;" % (symbol, len(payload)))
    lines.append("")
    with open(path, "w") as f:
        f.write("\n".join(lines))


def main():
    only = [a for a in sys.argv[1:] if not a.startswith("--")]
    check_only = "--check" in sys.argv
    fresh_dir = os.path.join(HERE, ".spv_fresh")
    os.makedirs(fresh_dir, exist_ok=True)

    stale = 0
    written = 0
    checked = 0
    for h in included_headers():
        hpath = os.path.join(HERE, h)
        if not os.path.exists(hpath):
            print("MISS  %-40s (included but not on disk)" % h)
            stale += 1
            continue
        sym = header_symbol(hpath)
        if not sym:
            print("ODD   %-40s (no `const unsigned char g_*[]` array)" % h)
            stale += 1
            continue
        base = shader_base(sym)
        if only and base not in only:
            continue
        checked += 1

        comp = resolve_comp(base)
        if comp is None:
            print("SKIP  %-40s base=%-30s (no .comp)" % (h, base))
            continue
        want = compile_comp(comp, os.path.join(fresh_dir, base + ".spv"))
        if want is None:
            stale += 1
            continue
        if want[:4] != SPIRV_MAGIC:
            print("ERROR %-40s compiled output is not SPIR-V" % h)
            stale += 1
            continue

        have, declared = header_payload(hpath)
        if have == want and declared == len(want):
            continue
        stale += 1
        print("%-5s %-40s embedded=%-6d fresh=%-6d declared=%-6d  [%s]"
              % ("WOULD" if check_only else "WRITE", h, len(have), len(want),
                 declared, os.path.basename(comp)))
        if not check_only:
            write_header(hpath, sym, want)
            written += 1

    print()
    print("checked=%d stale=%d%s" % (checked, stale,
                                     "" if check_only else " written=%d" % written))
    if check_only and stale:
        sys.exit(1)


if __name__ == "__main__":
    main()
